        if (indexes.length > 1) {
            for (let i = 1; i < indexes.length; i++) {
                const idxName = indexes[i].Key_name;
                await sequelize.query(`DROP INDEX \`${idxName}\` ON \`role\``);
                console.log(`已删除重复索引: ${idxName}`);
            }
        }
