    let cameraId = TEST_CAMERA_ID;
    let mp4Urls = []; // 收集所有 MP4 文件 URL，用于最终汇总

    try {
        // 1. 新增摄像头（先删除旧测试数据）
        console.log("[1/6] 准备测试摄像头...");
        try {
            await request("POST", "/api/video-stream/delete", { id: cameraId });
        } catch (e) { /* 不存在则忽略 */ }

        const addRes = await request("POST", "/api/video-stream/add", {
            name: "fluent-ffmpeg测试摄像头",
            protocol: "RTSP",
            url: RTSP_URL,
            resolution: "1920x1080",
            location: "测试点",
            recordEnabled: true,
            segmentDuration: 10 // 10秒一个录像分片，确保在 30 秒测试窗口内完成第一个分段
        });
        if (addRes.body.code !== 200) {
            throw new Error(`新增失败: ${addRes.body.msg}`);
        }
        cameraId = addRes.body.data.id;
        console.log(`  ✓ 新增成功 (id=${cameraId})`);

        // 2. 启动推流
        console.log("\n[2/6] 启动推流...");
        const startRes = await request("POST", "/api/video-stream/start", { id: cameraId });
        console.log(`  ✓ 推流已启动 (code=${startRes.body.code})`);

        // 3. 等待文件生成（RTSP 连接 + 转码需要时间，最多等 30 秒）
        console.log("\n[3/6] 等待 FFmpeg 转码输出（最多 30 秒）...");
        let hlsReady = false;
        let mp4Ready = false;
        const hlsM3u8 = path.join(__dirname, "..", "public", "live", String(cameraId), "index.m3u8");
        const recordDir = path.join(__dirname, "..", "public", "records", "fluent-ffmpeg测试摄像头", "测试点");

        for (let i = 0; i < 15; i++) {
            await sleep(2000);

            // 检查 HLS 播放列表
            const m3u8 = checkFile(hlsM3u8);
            if (m3u8.exists && m3u8.size > 0 && !hlsReady) {
                hlsReady = true;
                console.log(`  ✓ HLS 播放列表已生成 (${m3u8.size} bytes)`);
                console.log(`  HLS 直播地址: ${BASE_URL}/live/${cameraId}/index.m3u8`);
                const content = fs.readFileSync(hlsM3u8, "utf-8");
                console.log("  HLS 内容预览:");
                content.split("\n").slice(0, 5).forEach((line) => {
                    if (line.trim()) console.log(`    ${line}`);
                });
            }

            // 检查 MP4 录像文件（三层目录：name/location/dateTime）
            if (!mp4Ready) {
                const dateTimeDirs = listDir(recordDir);
                for (const dtDir of dateTimeDirs) {
                    const files = listDir(path.join(recordDir, dtDir)).filter(
                        (f) => f.endsWith(".mp4")
                    );
                    if (files.length > 0) {
                        mp4Ready = true;
                        const fileInfo = checkFile(path.join(recordDir, dtDir, files[0]));
                        const mp4Url = `${BASE_URL}/records/fluent-ffmpeg测试摄像头/测试点/${dtDir}/${files[0]}`;
                        mp4Urls.push(mp4Url);
                        console.log(
                            `  ✓ MP4 录像已生成 (${dtDir}/${files[0]}, ${(fileInfo.size / 1024).toFixed(1)} KB)`
                        );
                        console.log(`  MP4 录像地址: ${mp4Url}`);
                        break;
                    }
                }
            }

            if (hlsReady && mp4Ready) break;
            process.stdout.write(`  ... ${(i + 1) * 2}s\n`);
        }

        // 4. 验证 HLS 输出
        console.log("\n[4/6] 验证 HLS 直播输出...");
        const hlsDir = path.join(__dirname, "..", "public", "live", String(cameraId));
        const hlsFiles = listDir(hlsDir);
        console.log(`  HLS 文件数: ${hlsFiles.length}`);
        hlsFiles.forEach((f) => {
            const info = checkFile(path.join(hlsDir, f));
            console.log(`    ${f} (${info.size} bytes)`);
        });
        console.log(hlsReady ? "  ✓ HLS 直播验证通过" : "  ✗ HLS 直播验证失败");
        if (hlsReady) {
            console.log(`  HLS 浏览器访问地址: ${BASE_URL}/live/${cameraId}/index.m3u8`);
        }

        // 5. 验证 MP4 录像
        console.log("\n[5/6] 验证 MP4 录像文件...");
        const dateDirs = listDir(recordDir);
        let totalMp4 = 0;
        for (const dd of dateDirs) {
            const mp4Files = listDir(path.join(recordDir, dd)).filter((f) =>
                f.endsWith(".mp4")
            );
            totalMp4 += mp4Files.length;
            mp4Files.forEach((f) => {
                const info = checkFile(path.join(recordDir, dd, f));
                const mp4Url = `${BASE_URL}/records/fluent-ffmpeg测试摄像头/测试点/${dd}/${f}`;
                console.log(`    ${dd}/${f} (${(info.size / 1024).toFixed(1)} KB)`);
                console.log(`    访问: ${mp4Url}`);
            });
        }
        console.log(`  录像文件总数: ${totalMp4}`);
        console.log(mp4Ready ? "  ✓ MP4 录像验证通过" : "  ✗ MP4 录像验证失败");

        // 6. 停止推流 + 清理
        console.log("\n[6/6] 停止推流并清理测试数据...");
        const stopRes = await request("POST", "/api/video-stream/stop", { id: cameraId });
        console.log(`  ✓ 推流已停止 (code=${stopRes.body.code})`);

        const delRes = await request("POST", "/api/video-stream/delete", { id: cameraId });
        console.log(`  ✓ 测试数据已清理 (code=${delRes.body.code})`);

        // 最终结果
        console.log("\n========================================");
        if (hlsReady && mp4Ready) {
            console.log("  ✅ 测试全部通过！");
            console.log("  RTSP 转码 -> HLS 直播 + MP4 录像");
            console.log("  全链路功能正常");
            console.log("\n  浏览器可访问的地址:");
            console.log(`  HLS 直播: ${BASE_URL}/live/${cameraId}/index.m3u8`);
            if (mp4Urls.length > 0) {
                console.log(`  MP4 录像 (${mp4Urls.length} 个):`);
                mp4Urls.forEach((url) => console.log(`    ${url}`));
            }
        } else {
            console.log("  ⚠️  部分测试未通过");
            if (!hlsReady) console.log("  - HLS 直播文件未生成");
            if (!mp4Ready) console.log("  - MP4 录像文件未生成");
            console.log("  可能原因：RTSP 地址不可达或 FFmpeg 配置问题");
        }
        console.log("========================================\n");
    } catch (error) {
        console.error(`\n❌ 测试异常: ${error.message}`);
        console.log("\n请确保:");
        console.log("1. 服务器已启动 (pnpm start)");
        console.log("2. MySQL 服务已运行");
        console.log("3. FFmpeg 完整版已安装");
        console.log("4. RTSP 摄像头地址可访问");
    }
})
